package com.openggf.game.soniccd;
import com.openggf.GameLoop;
import com.openggf.game.save.SaveManager;
import com.openggf.game.session.SessionManager;
import com.openggf.game.soniccd.level.*;
import com.openggf.game.soniccd.objects.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.parallel.Isolated;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import static org.junit.jupiter.api.Assertions.*;
import static com.openggf.game.soniccd.objects.CdObjectState.ByteField.*;
import static com.openggf.game.soniccd.objects.CdObjectState.WordField.*;
/** Tests FIRST/allJavaUNRUN. Explicitly constructed physical127 vectors over real Boot/Ready;
 * the untouched public240-return test alone establishes natural continuation. */
@Isolated class TestCdOriginalTtTimePostWorld extends TestCdOriginalR11LoadingWorld {
 @Test void constructedInitAndNextMainUseTheCachedOriginalAssetsAndReplayFullCourse()throws Exception{try(var f=start()){
  assertSame(f.source.timePostAssets(),field(f.body,"assets"));var seed=seed(f,0,8,0);f.placement.pool().write(seed);var registry=SessionManager.getCurrentGameplayMode().getRewindRegistry();var full=registry.capture();var course=registry.captureCourse();step(f.loop,0);
  var row=f.placement.pool().state(127);assertEquals(2,row.routine());assertEquals(0x209CDE,row.longBits(CdObjectState.LongField.MAPPINGS));assertEquals(0x5A8,row.word(TILE));assertEquals(32,row.unsignedByte(Y_RADIUS));assertEquals(14,row.unsignedByte(X_RADIUS));assertEquals(15,row.unsignedByte(WIDTH));assertEquals(8,row.unsignedByte(ANIMATION));assertEquals(10,row.unsignedByte(MAP_FRAME));assertEquals(0xDF,row.unsignedByte(COLLISION_TYPE));assertEquals(seed.unsignedByte(LAYER),row.unsignedByte(LAYER));var expected=image(f.module);
  for(boolean c:new boolean[]{false,true}){if(c)registry.restoreCourse(course);else registry.restore(full);step(f.loop,0);CdCapturedValueAssertions.assertCapturedValueEquals(expected,image(f.module));}step(f.loop,0);assertEquals(2,f.placement.pool().state(127).routine());assertFalse(f.module.originalR11EntryFrame().closed());
 }}
 @Test void constructedPastContactCommitsRawMinusOneSavedBitAndExactlyOneVoiceWithoutLayerRead()throws Exception{try(var f=start()){
  f.placement.pool().write(seed(f,2,8,1));var calls=record(f.body);var layer=f.module.originalR11LoadingImage().globals().layerByte();step(f.loop,0);var out=f.placement.pool().state(127);
  assertEquals(4,out.routine());assertEquals(60,out.unsignedByte(TIME_POST_SPIN));assertEquals(0,out.unsignedByte(COLLISION_STATUS));assertEquals(255,f.module.originalR11EntryFrame().environment().movement().gates().timeWarpDirection());assertEquals(1,f.placement.savedFlag(200,1)&1);assertEquals(layer,f.module.originalR11LoadingImage().globals().layerByte());assertFalse(calls.stream().anyMatch(c->c.site()==CdTimePost.Site.LAYER_READ));assertEquals(List.of(CdTimePost.SubCpuCommand.SCMD_PASTSFX),voices(f.binding));
 }}
 @Test void constructedFutureContactUsesBothActualDirectionStoresBeforeOneSubCpuRequest()throws Exception{try(var f=start()){
  f.placement.pool().write(seed(f,2,9,1));var calls=record(f.body);step(f.loop,0);var direction=calls.stream().filter(c->c.site()==CdTimePost.Site.DIRECTION_STORE).map(c->(CdTimePost.DirectionCall)c.argument()).toList();assertEquals(2,direction.size());assertEquals(0,direction.get(0).expectedRawDirection());assertEquals(255,direction.get(0).rawDirection());assertEquals(255,direction.get(1).expectedRawDirection());assertEquals(1,direction.get(1).rawDirection());assertEquals(1,f.module.originalR11EntryFrame().environment().movement().gates().timeWarpDirection());assertEquals(List.of(CdTimePost.SubCpuCommand.SCMD_FUTURESFX),voices(f.binding));assertFalse(calls.stream().anyMatch(c->c.site()==CdTimePost.Site.LAYER_READ));var sites=calls.stream().map(CdTimePost.OriginalCall::site).toList();assertTrue(sites.indexOf(CdTimePost.Site.SUB_CPU)<sites.indexOf(CdTimePost.Site.DRAW));
 }}
 @Test void constructedRefusedSubCpuRetainsTheNativeDirectionAndObjectPrefix()throws Exception{subCpuFault(false);}
 @Test void constructedLandedSubCpuThenFaultRetainsItsOneRequestAndOriginalThrowable()throws Exception{subCpuFault(true);}
 @Test void idleAndWrongThreadCannotRunThePrivateWorldTimePostOrReadGlobals()throws Exception{try(var f=start()){
  f.placement.pool().write(seed(f,0,8,0));var before=f.placement.capture();var frame=f.module.originalR11EntryFrame();var actor=frame.captureActor();var shared=frame.captureShared();assertThrows(IllegalStateException.class,()->f.body.runWithReads(127,unreachedReads()));var failure=new AtomicReference<Throwable>();var t=new Thread(()->{try{f.body.runWithReads(127,unreachedReads());}catch(Throwable e){failure.set(e);}});t.start();t.join(5000);assertFalse(t.isAlive());assertInstanceOf(IllegalStateException.class,failure.get());assertEquals(before.pool().slots(),f.placement.capture().pool().slots());assertArrayEquals(before.savedFlags().copy(),f.placement.capture().savedFlags().copy());assertEquals(actor,frame.captureActor());assertEquals(shared,frame.captureShared());
 }}
 @Test void constructedMonitorSubtypeBelowEightNowUsesMonitorAndPreservesTheTimePostDirectionOwner()throws Exception{try(var f=start()){
  var seed=seed(f,0,2,0);f.placement.pool().write(seed);var before=f.placement.savedFlag(200,1);var frame=f.module.originalR11EntryFrame();int direction=frame.environment().movement().gates().timeWarpDirection();step(f.loop,0);var value=f.placement.pool().state(127);assertEquals(0x19,value.id());assertEquals(2,value.routine());assertEquals(2,value.unsignedByte(ANIMATION));assertEquals(0x209CDE,value.longBits(CdObjectState.LongField.MAPPINGS));assertEquals(before,f.placement.savedFlag(200,1));assertEquals(direction,frame.environment().movement().gates().timeWarpDirection());assertTrue(voices(f.binding).isEmpty());assertFalse(frame.closed());
 }}
 @Test void completedNativeReceiptCannotBeReusedByTheKernelOrPrivateWorldObserver()throws Exception{try(var f=start()){
  f.placement.pool().write(seed(f,0,8,0));var calls=record(f.body);step(f.loop,0);var before=f.placement.capture();var old=calls.getFirst();assertThrows(IllegalStateException.class,()->f.body.requireCurrent(old));var observer=(CdTimePost.NativeObserver)field(f.body,"originalObserver");assertThrows(IllegalStateException.class,()->observer.before(old));assertEquals(before.pool().slots(),f.placement.capture().pool().slots());assertArrayEquals(before.savedFlags().copy(),f.placement.capture().savedFlags().copy());
 }}
 private void subCpuFault(boolean landed)throws Exception{try(var f=start()){
  f.placement.pool().write(seed(f,2,9,1));var actual=(CdTimePost.SubCpuCall)field(f.body,"subCpu");var fault=new Fault();set(f.body,"subCpu",(CdTimePost.SubCpuCall)c->{if(landed)actual.request(c);throw fault;});var frame=f.module.originalR11EntryFrame();assertSame(fault,assertThrows(Fault.class,()->step(f.loop,0)));var row=f.placement.pool().state(127);assertEquals(4,row.routine());assertEquals(60,row.unsignedByte(TIME_POST_SPIN));assertEquals(0,row.unsignedByte(COLLISION_STATUS));assertEquals(1,frame.environment().movement().gates().timeWarpDirection());assertEquals(1,f.placement.savedFlag(200,1)&1);assertEquals(landed?List.of(CdTimePost.SubCpuCommand.SCMD_FUTURESFX):List.of(),voices(f.binding));assertEquals(0,fault.getSuppressed().length);assertTrue(frame.closed());
 }}
 private static CdObjectState seed(Fixture f,int routine,int subtype,int contact){var motion=f.module.originalR11EntryFrame().state().motion();var row=f.placement.pool().state(127).moveByte(ID,0x19).moveByte(SUBTYPE,subtype).moveByte(ROUTINE,routine).moveByte(COLLISION_STATUS,contact).moveByte(SAVED_FLAGS_ID,200).moveByte(SPRITE_FLAGS,4).moveByte(LAYER,0x55).moveWord(X,((motion.centreX16_16()>>>16)+96)&65535).moveWord(Y,motion.centreY16_16()>>>16);if(routine!=0)row=row.moveLong(CdObjectState.LongField.MAPPINGS,0x209CDE).moveWord(TILE,0x5A8).moveByte(PRIORITY,3).moveByte(WIDTH,15).moveByte(Y_RADIUS,32).moveByte(X_RADIUS,14).moveByte(ANIMATION,subtype).moveByte(MAP_FRAME,subtype==8?10:12).moveByte(COLLISION_TYPE,0xDF);return row;}
 private Fixture start()throws Exception{var source=TestCdOriginalBootPrefix.source();var saves=new SaveManager(root);var profile=CdSaveProfile.fromTemplate(source.initialSaveAssets().orElseThrow()).withPatch(new CdIpxProgress.SavePatch(OptionalInt.of(0x200),OptionalInt.of(4),OptionalInt.of(0x90),OptionalInt.of(0),OptionalInt.of(0x35),OptionalInt.of(2),OptionalInt.of(3)));saves.writeSlot("scd",1,profile.encode());var attempt=SonicCdGameModule.prepareSelectedProfile(source,saves,1,SonicCdGameModule.ProfileEntry.LOAD_GAME,0);var module=attempt.module().orElseThrow();var b=boot();try{var loop=b.bootSonicCdSelectedProfile(source,attempt);for(int n=0;n<256&&module.originalR11LoadingPrefix().main().levelStartedByte()!=1;n++)step(loop,0);assertEquals(SonicCdR31aLoadingVisit.Phase.READY,module.originalR11LoadingImage().phase());var binding=field(field(module,"r11World"),"binding");var placement=(CdObjectPlacementRuntime)field(binding,"placement");assertEquals(0,placement.pool().state(127).id());var frame=module.originalR11EntryFrame();return new Fixture(b,loop,module,binding,placement,((CdLevelLoadingSource)field(binding,"ttSource")).objectSource(),(CdTimePost)field(binding,"timePost"));}catch(Exception|Error e){b.close();throw e;}}
 private record Fixture(com.openggf.tools.HeadlessGameBoot boot,GameLoop loop,SonicCdGameModule module,Object binding,CdObjectPlacementRuntime placement,CdProgrammeObjectSource source,CdTimePost body)implements AutoCloseable{public void close(){try{SessionManager.clear();}finally{try{com.openggf.game.GameServices.graphics().cleanup();}finally{boot.close();}}}}
 private static Object image(SonicCdGameModule m){var f=m.originalR11EntryFrame();var p=m.originalR11PlacementImage();return List.of(f.captureActor(),f.captureShared(),p.status(),p.pool().slots(),p.savedFlags(),m.originalR11LoadingPrefix(),m.originalR11LoadingImage(),m.originalR11FirstLoad(),m.originalLoadingWaterImage(),m.originalLoadingWaterPalette(),m.originalR11WorldImage(),m.programServicesState(),m.selectedProfileState());}
 @SuppressWarnings("unchecked") private static List<CdTimePost.SubCpuCommand> voices(Object binding)throws Exception{return((List<SonicCdGameModule.PastSound>)field(binding,"sounds")).stream().filter(SonicCdGameModule.PastTimePostSubCpu.class::isInstance).map(s->((SonicCdGameModule.PastTimePostSubCpu)s).command()).toList();}
 private static List<CdTimePost.OriginalCall> record(CdTimePost body)throws Exception{var actual=(CdTimePost.NativeObserver)field(body,"originalObserver");var calls=new ArrayList<CdTimePost.OriginalCall>();set(body,"originalObserver",new CdTimePost.NativeObserver(){public void before(CdTimePost.OriginalCall c){actual.before(c);calls.add(c);}public void after(CdTimePost.OriginalCall c){actual.after(c);}public void failed(CdTimePost.OriginalCall c,Throwable failure){actual.failed(c,failure);}});return calls;}
 private static CdTimePost.PastGlobals unreachedReads(){return new CdTimePost.PastGlobals(){private int no(){throw new AssertionError("Idle/foreign World cannot reach a native global read");}public int rawTimeZone(){return no();}public int rawTimeWarpDirection(){return no();}public int cameraXWord(){return no();}public int timeAttackMode(){return no();}public int zone(){return no();}public OptionalInt layer(){throw new AssertionError("No layer read");}};}
 private static Object field(Object owner,String name)throws Exception{var f=owner.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(owner);}
 private static void set(Object owner,String name,Object value)throws Exception{var f=owner.getClass().getDeclaredField(name);f.setAccessible(true);f.set(owner,value);}
 private static final class Fault extends RuntimeException{}
}
